export interface Check {
  id: string;
  suite_id: string;
  name: string;
  kind: string;
  /** `auto` = added by automatic coverage; `suggestion` = an accepted suggestion (ADR 0047). */
  origin?: 'user' | 'auto' | 'suggestion';
  /** Check engine (ADR 0036) — `gx` (default) or `dmf` on a Snowflake connection.
   *  Optional so pre-0036 fixtures need no change. */
  engine?: string;
  expectation_type: string;
  /** DQ dimension (ADR 0038). `null` = unclassified — render it as a coverage
   *  gap, never bucket it silently. Optional so pre-0038 fixtures need no change. */
  dimension?: string | null;
  config: Record<string, unknown>;
  /** Comparison source ref (ADR 0015) — set exactly for kind='comparison'.
   *  Optional in the type so pre-0015 fixtures/readers need no change. */
  source_connection_id?: string | null;
  warn_threshold: number | null;
  fail_threshold: number | null;
  critical_threshold: number | null;
  /** Alert suppression (#370): in the future = alerts muted until then; null /
   *  past = active. Set via the snooze endpoints, never PATCH. */
  alert_snoozed_until: string | null;
}


/** Mirrors `CheckUpdate` — all fields optional; kind is immutable. */
export interface CheckUpdate {
  name?: string;
  /** Check engine (ADR 0036) — switch an existing check between `gx`/`dmf`
   *  (e.g. a freshness check, the one type both engines evaluate). */
  engine?: string;
  expectation_type?: string;
  /** Re-classifiable at any time (ADR 0038 §2). */
  dimension?: string | null;
  config?: Record<string, unknown>;
  /** Repoint a comparison check's source (never clearable). */
  source_connection_id?: string | null;
  warn_threshold?: number | null;
  fail_threshold?: number | null;
  critical_threshold?: number | null;
}

export async function createCheck(suiteId: string, payload: CheckCreate): Promise<Check> {
  const { data } = await api.post<Check>(`/suites/${suiteId}/checks`, payload);
  return data;
}

export async function updateCheck(
  suiteId: string,
  checkId: string,
  payload: CheckUpdate,
): Promise<Check> {
  const { data } = await api.patch<Check>(`/suites/${suiteId}/checks/${checkId}`, payload);
  return data;
}

export async function deleteCheck(suiteId: string, checkId: string): Promise<void> {
  await api.delete(`/suites/${suiteId}/checks/${checkId}`);
}

/** Mute a noisy check's alerts for N hours (edit-gated; backend caps at 720h). */
export async function snoozeCheck(suiteId: string, checkId: string, hours: number): Promise<Check> {
  const { data } = await api.post<Check>(`/suites/${suiteId}/checks/${checkId}/snooze`, { hours });
  return data;
}

/** Clear a check's alert snooze — alerts fire again immediately (edit-gated). */
export async function clearCheckSnooze(suiteId: string, checkId: string): Promise<Check> {
  const { data } = await api.delete<Check>(`/suites/${suiteId}/checks/${checkId}/snooze`);
  return data;
}

/** Result of a bulk check action — all-or-nothing, so `affected` is every check named. */
export interface BulkChecksResult {
  affected: number;
  checks: Check[];
}

/** Snooze many checks at once (edit-gated; refused whole if any id is not in the suite). */
export async function bulkSnoozeChecks(
  suiteId: string,
  checkIds: string[],
  hours: number,
): Promise<BulkChecksResult> {
  const { data } = await api.post<BulkChecksResult>(`/suites/${suiteId}/checks-bulk/snooze`, {
    check_ids: checkIds,
    hours,
  });
  return data;
}

export async function bulkUnsnoozeChecks(
  suiteId: string,
  checkIds: string[],
): Promise<BulkChecksResult> {
  const { data } = await api.post<BulkChecksResult>(`/suites/${suiteId}/checks-bulk/unsnooze`, {
    check_ids: checkIds,
  });
  return data;
}

/** Delete many checks at once — each check's results and history go with it. */
export async function bulkDeleteChecks(
  suiteId: string,
  checkIds: string[],
): Promise<BulkChecksResult> {
  const { data } = await api.post<BulkChecksResult>(`/suites/${suiteId}/checks-bulk/delete`, {
    check_ids: checkIds,
  });
  return data;
}

/** Per tier: a number sets it, `null` clears it, an absent key keeps each check's own value. */
export interface BulkThresholds {
  warn_threshold?: number | null;
  fail_threshold?: number | null;
  critical_threshold?: number | null;
}

/** Set the same thresholds on many checks (edit-gated; refused whole if any check can't take them). */
export async function bulkSetThresholds(
  suiteId: string,
  checkIds: string[],
  thresholds: BulkThresholds,
): Promise<BulkChecksResult> {
  const { data } = await api.post<BulkChecksResult>(`/suites/${suiteId}/checks-bulk/thresholds`, {
    check_ids: checkIds,
    ...thresholds,
  });
  return data;
}

